import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.LocalTime;
import java.time.OffsetDateTime;
import java.time.Period;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Date;

public class Main {
    private static final DateTimeFormatter API_TIME = DateTimeFormatter.ISO_OFFSET_DATE_TIME;

    public static void main(String[] args) {
        LocalDate billDate = LocalDate.of(2026, 6, 18);
        LocalTime storeOpen = LocalTime.of(9, 0);
        LocalDateTime meetingLocal = LocalDateTime.of(2026, 6, 18, 10, 30);
        ZoneId shanghai = ZoneId.of("Asia/Shanghai");
        ZonedDateTime meetingInShanghai = meetingLocal.atZone(shanghai);
        Instant auditTime = meetingInShanghai.toInstant();
        OffsetDateTime apiTime = auditTime.atOffset(ZoneOffset.UTC);
        String text = apiTime.format(API_TIME);
        OffsetDateTime parsed = OffsetDateTime.parse(text, API_TIME);

        Date legacyDate = Date.from(auditTime);
        Instant back = legacyDate.toInstant();

        ZoneId newYork = ZoneId.of("America/New_York");
        LocalDateTime gapLocal = LocalDateTime.of(2026, 3, 8, 2, 30);
        ZonedDateTime resolvedGap = gapLocal.atZone(newYork);

        LocalDateTime overlapLocal = LocalDateTime.of(2026, 11, 1, 1, 30);
        ZonedDateTime earlierOffset = overlapLocal.atZone(newYork);
        ZonedDateTime laterOffset = earlierOffset.withLaterOffsetAtOverlap();

        ZonedDateTime beforeGap = ZonedDateTime.of(2026, 3, 8, 1, 30, 0, 0, newYork);
        ZonedDateTime plusCalendarDay = beforeGap.plus(Period.ofDays(1));
        ZonedDateTime plusTwentyFourHours = beforeGap.plus(Duration.ofHours(24));
        long periodElapsedHours = Duration.between(beforeGap.toInstant(), plusCalendarDay.toInstant()).toHours();
        long durationElapsedHours = Duration.between(beforeGap.toInstant(), plusTwentyFourHours.toInstant()).toHours();

        System.out.println("bill/open: " + billDate + " " + storeOpen);
        System.out.println("meeting instant: " + auditTime);
        System.out.println("api text: " + text);
        System.out.println("NY gap resolved: " + resolvedGap);
        System.out.println("NY overlap offsets: " + earlierOffset.getOffset() + " / " + laterOffset.getOffset());
        System.out.println("Period day hours: " + periodElapsedHours + ", Duration hours: " + durationElapsedHours);

        assert billDate.equals(LocalDate.of(2026, 6, 18));
        assert storeOpen.equals(LocalTime.of(9, 0));
        assert auditTime.equals(Instant.parse("2026-06-18T02:30:00Z"));
        assert parsed.toInstant().equals(auditTime);
        assert back.equals(auditTime);
        assert resolvedGap.getHour() == 3 && resolvedGap.getMinute() == 30;
        assert earlierOffset.getOffset().equals(ZoneOffset.ofHours(-4));
        assert laterOffset.getOffset().equals(ZoneOffset.ofHours(-5));
        assert Duration.between(earlierOffset.toInstant(), laterOffset.toInstant()).equals(Duration.ofHours(1));
        assert periodElapsedHours == 23;
        assert durationElapsedHours == 24;
    }
}
